INSERT INTO `prayer_requests` (`id`, `user_id`, `body`, `created_at`, `answered_at`) VALUES
('101', '1', 'Please pray for our family as we manage a new season of change. We are trusting God for wisdom and unity.', '2026-09-09 04:01:11', NULL),
('102', '1', 'Pray for my health. I have been battling recurring migraines and I am asking the Lord for complete healing.', '2026-09-12 05:54:12', NULL),
('103', '1', 'I am starting a new chapter in my career. Pray for clarity, favour, and that I honour God in all my work.', '2026-09-04 12:51:31', NULL),
('104', '1', 'Please intercede for me as I grow in faith and prayer life. I long for a deeper walk with Christ.', '2026-08-31 19:29:52', NULL),
('105', '1', 'Pray for my loved ones who have not yet accepted Christ. I believe God is still working in their hearts.', '2026-09-08 19:56:02', '2026-09-16 10:58:48'),
('106', '22', 'Please pray for my final exams next week. I have worked hard but I feel anxious and need God''s peace and clarity.', '2026-09-09 09:13:05', NULL),
('107', '22', 'My father needs a successful kidney transplant. The medical team says he is a good candidate, please stand with us in prayer.', '2026-09-07 19:53:41', '2026-09-15 16:16:15'),
('108', '22', 'Pray for unity in my family during this stressful season. Small disagreements keep turning into big arguments.', '2026-09-09 13:43:45', NULL),
('109', '22', 'I am trusting God for a new job opportunity. I have applied to many places and I am waiting on His timing.', '2026-08-26 15:27:37', NULL),
('110', '22', 'Please intercede for my younger sister who has been battling depression. She needs hope and healing from the Lord.', '2026-09-13 07:08:07', NULL),
('111', '23', 'Please pray for my marriage. We love each other but communication has been strained lately, we need wisdom.', '2026-09-04 23:35:35', NULL),
('112', '23', 'I have an important job interview on Thursday. Pray that I present well and that God opens the right door.', '2026-08-31 06:07:09', NULL),
('113', '23', 'Pray for my startup to find stability. Cash flow is tight and I need breakthrough and favour with investors.', '2026-08-26 18:06:20', NULL),
('114', '23', 'My mother has been feeling unwell for weeks and the doctors are not sure what is wrong. Pray for a clear diagnosis.', '2026-09-08 12:43:37', NULL),
('115', '23', 'I am considering relocating to another city for work. Pray for clear direction about whether this move is God''s will.', '2026-09-08 12:50:04', NULL),
('116', '24', 'Lift up my pregnancy in prayer. The doctors have flagged some concerns and I am trusting God for a safe delivery.', '2026-09-04 03:00:12', '2026-09-08 10:16:15'),
('117', '24', 'Pray for my vegetable farming business. The rains failed this season and I need provision for my family.', '2026-09-02 05:55:22', NULL),
('118', '24', 'My church is planning a retreat and I am coordinating it. Pray that everything comes together smoothly.', '2026-08-30 18:11:16', NULL),
('119', '24', 'Please pray for reconciliation with my estranged brother. It has been three years since we last spoke.', '2026-09-08 20:06:43', NULL),
('120', '24', 'I am applying to graduate school. Pray that I gain admission into the programme I have been dreaming of.', '2026-09-14 00:56:21', NULL),
('121', '25', 'Pray for my final year project. I am behind schedule and under a lot of pressure to finish by the deadline.', '2026-08-28 10:36:26', NULL),
('122', '25', 'My grandmother needs surgery to remove a tumour. Pray for the surgeons and for her strength.', '2026-09-11 15:46:43', NULL),
('123', '25', 'I have been struggling with temptation and wanted to ask the community to hold me up in prayer.', '2026-08-31 08:00:45', NULL),
('124', '25', 'Pray for my siblings and I as we plan our father''s funeral. It is a painful time but we trust God.', '2026-09-15 08:52:11', NULL),
('125', '25', 'I am leading a youth Bible study on Fridays. Pray that the young people''s hearts stay open and hungry for God.', '2026-09-15 15:44:57', '2026-09-15 13:16:15'),
('126', '26', 'Please pray for my visa application. I have been waiting for months and my dream job abroad depends on it.', '2026-09-03 16:44:37', NULL),
('127', '26', 'My twins have been sick on and off for a month. Pray for their full rest, protection and good health.', '2026-09-05 16:57:12', NULL),
('128', '26', 'Pray that I find a godly mentor. I sense God is calling me to grow but I need guidance and accountability.', '2026-09-06 18:41:47', NULL),
('129', '26', 'I had a car accident last week. I am grateful to be alive but my leg injury is slow to heal, please pray.', '2026-08-26 17:07:03', NULL),
('130', '26', 'Pray for the children I teach. Many of them face tough home situations and I want to be a source of stability.', '2026-09-15 08:13:49', NULL),
('131', '27', 'Pray for my scholarship application. My family cannot afford my tuition without it and the decision is due soon.', '2026-09-14 09:09:48', NULL),
('132', '27', 'I recently lost my job. Please pray for peace, provision, and the right opportunity to come my way.', '2026-09-08 14:27:47', NULL),
('133', '27', 'My church is about to launch a community feeding programme. Pray for volunteers and enough funds.', '2026-08-31 18:37:09', NULL),
('134', '27', 'Pray for my relationship with my father. We rarely talk and I want to rebuild that bond with grace.', '2026-08-31 11:50:49', '2026-09-12 10:16:15'),
('135', '27', 'I have been waking up with terrible anxiety at night. Pray that God calms my mind and fills me with trust.', '2026-09-15 01:00:13', NULL),
('136', '28', 'Please pray for my new business venture. I am launching a bakery next month and everything needs to align.', '2026-09-06 10:41:08', NULL),
('137', '28', 'My uncle is on life support after a sudden illness. The family is gathered, please hold us up in prayer.', '2026-09-12 01:37:04', NULL),
('138', '28', 'Pray that I overcome my fear of public speaking. I keep being asked to share at church but I freeze up.', '2026-08-31 15:54:23', NULL),
('139', '28', 'I am discerning whether to pursue full-time ministry. Pray for God to make His calling unmistakable.', '2026-09-07 15:02:12', NULL),
('140', '28', 'Pray for my health. I have been dealing with chronic fatigue and I am asking the Lord for strength daily.', '2026-09-16 08:56:41', NULL),
('141', '29', 'Pray for my project team. We are shipping a major release and tensions are high, we need harmony and focus.', '2026-09-06 07:33:57', NULL),
('142', '29', 'My wife and I are hoping for a child. We have been trying for two years and we are trusting God''s timing.', '2026-09-01 13:10:28', NULL),
('143', '29', 'Pray for my knees, they have been painful making it hard to kneel to pray or play with my son.', '2026-09-02 11:05:06', '2026-09-16 07:16:15'),
('144', '29', 'I am mentoring two young men who recently gave their lives to Christ. Pray for wisdom as I disciple them.', '2026-09-04 03:14:37', NULL),
('145', '29', 'Please pray for my brother who has drifted from the faith. Our family intercedes for his return daily.', '2026-09-01 02:40:50', NULL),
('146', '30', 'Pray for my nursing exams. I am studying while working night shifts and I need supernatural energy.', '2026-09-05 04:58:16', NULL),
('147', '30', 'I lost my twin sister two years ago and grief still overwhelms me some days. Pray for my heart''s healing.', '2026-09-13 14:03:17', NULL),
('148', '30', 'Pray for safe travels as I relocate to a new region for work in two weeks.', '2026-09-15 23:51:00', NULL),
('149', '30', 'My mother''s church needs a new roof after the storm. Pray for provision so the congregation can rebuild.', '2026-08-30 04:03:43', NULL),
('150', '30', 'Please pray that I hear clearly from God about a big decision I must make before the end of the year.', '2026-09-07 21:49:04', '2026-09-07 10:16:15');
