INSERT INTO `testimonies` (`id`, `prayer_request_id`, `user_id`, `body`, `created_at`) VALUES
('2', '107', '22', 'God answered beyond what I asked. The doctors confirmed the treatment worked and my father is recovering at home. Praise the Lord!', '2026-09-15 18:12:51'),
('3', '116', '24', 'The Lord came through. I passed the exams with good grades and the whole experience deepened my trust in Him.', '2026-09-08 11:48:40'),
('4', '125', '25', 'God moved in a way I did not expect. The door opened at the perfect time and I now have a new opportunity.', '2026-09-15 15:13:29'),
('5', '134', '27', 'Our prayers were answered! Mama is doing much better and the whole family is overwhelmed with gratitude.', '2026-09-12 11:56:38'),
('6', '143', '29', 'The Lord answered clearly. Peace has returned to our home and what seemed impossible became possible.', '2026-09-16 09:05:32'),
('7', '150', '30', 'God did it again. The breakthrough came just when I was about to give up. Forever grateful for this community''s prayers.', '2026-09-07 10:31:19'),
('9', '105', '1', 'God is a GOOOD GOOD GOD', '2026-09-16 10:59:45');
INSERT INTO `devotionals` (`id`, `title`, `scripture`, `body`, `mins`, `created_at`) VALUES
('1', 'Strength in Silence', 'Psalm 46:10', 'In a world that never stops talking, this devotional invites you to find peace in stillness and to listen for the still, small voice of God.', '5', '2026-09-17 10:41:12'),
('2', 'The Courage to Ask', 'Matthew 7:7', 'We often carry burdens alone when God invites us simply to ask. Learn how humble, persistent prayer changes the posture of the heart.', '7', '2026-09-17 10:41:12'),
('3', 'Walking in Forgiveness', 'Colossians 3:13', 'Forgiveness frees the forgiver as much as the forgiven. Reflect on releasing old hurts and extending the grace you have received.', '6', '2026-09-17 10:41:12'),
('4', 'Gratitude That Transforms', '1 Thessalonians 5:18', 'Giving thanks in every circumstance reshapes how we see our day. Discover the practice of counting blessings as a path to joy.', '4', '2026-09-17 10:41:12'),
('5', 'Trusting God''s Timing', 'Ecclesiastes 3:1', 'Waiting on the Lord can feel endless. This devotional explores how seasons of waiting shape faith and mature our trust in His perfect timing.', '6', '2026-09-17 10:41:12');
INSERT INTO `fellowship_events` (`id`, `title`, `schedule`, `location`, `body`, `created_at`) VALUES
('1', 'Wednesday Prayer Night', 'Every Wednesday · 7:00 PM', 'Community Hall, Room 2', 'Come together for an evening of worship, intercession, and encouragement.', '2026-09-17 10:41:17'),
('2', 'Friday Bible Study', 'Fridays · 6:30 PM', 'Main Sanctuary', 'Verse-by-verse study of the Gospel of John. All are welcome, bring a friend.', '2026-09-17 10:41:17'),
('3', 'Community Outreach', 'Saturday, October 3 · 9:00 AM', 'Church Parking Lot', 'Join us as we serve our neighborhood with meals, fellowship, and prayer.', '2026-09-17 10:41:17'),
('4', 'Women''s Breakfast', 'Second Saturday · 8:30 AM', 'Fellowship Hall', 'A morning of good food, testimonies, and encouragement for the women of our community.', '2026-09-17 10:41:17'),
('5', 'Youth Praise Night', 'Friday, October 17 · 6:00 PM', 'Main Sanctuary', 'Worship, games, and the Word for young people. Bring a friend and a joyful heart.', '2026-09-17 10:41:17');
